// Great Tea Road 2.0 — original procedural 3D reconstructions.
// Historical photographs are NOT generated by this script.
// Modern interpretive models, not photogrammetric replicas.
const host=document.getElementById("scene"), note=document.getElementById("sceneNote");
let T;
try {T=await import("https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js")}
catch(e){console.warn("Three.js unavailable",e);note.style.display="block"}
if(T){
try{
const scene=new T.Scene();scene.background=new T.Color("#343c36");scene.fog=new T.Fog("#343c36",13,34);
const camera=new T.PerspectiveCamera(57,1,.1,75);
const renderer=new T.WebGLRenderer({antialias:true,powerPreference:"high-performance"});
renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.8));renderer.outputColorSpace=T.SRGBColorSpace;
renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.5;
host.prepend(renderer.domElement);document.getElementById("fallback").style.display="none";note.style.display="none";
const mat=(c,r=.85,m=0)=>new T.MeshStandardMaterial({color:c,roughness:r,metalness:m});
const wood=mat("#6d4b30"),woodL=mat("#a88153"),gold=mat("#bfa16b",.45,.4),tea=mat("#624a31"),
paper=mat("#ead6af"),red=mat("#923c34"),floor=mat("#a99f8d"),wall=mat("#c5c0b0"),cloth=mat("#a98554"),dark=mat("#28352f"),
glass=new T.MeshPhysicalMaterial({color:"#bed6cc",roughness:.08,transparent:true,opacity:.14,depthWrite:false,side:T.DoubleSide});
function mesh(parent,geo,m,x=0,y=0,z=0){const o=new T.Mesh(geo,m);o.position.set(x,y,z);parent.add(o);return o}
const box=(p,w,h,d,x,y,z,m)=>mesh(p,new T.BoxGeometry(w,h,d),m,x,y,z);
const cyl=(p,r1,r2,h,x,y,z,m)=>mesh(p,new T.CylinderGeometry(r1,r2,h,16),m,x,y,z);
const sphere=(p,r,x,y,z,m)=>mesh(p,new T.SphereGeometry(r,16,12),m,x,y,z);
const cone=(p,r,h,x,y,z,m)=>mesh(p,new T.ConeGeometry(r,h,4),m,x,y,z);
const ring=(p,r,t,x,y,z,m)=>mesh(p,new T.TorusGeometry(r,t,9,26),m,x,y,z);
box(scene,22,.22,14,0,-.11,0,floor);
box(scene,22,7,.22,0,3.45,-7,wall);box(scene,.22,7,14,-11,3.45,0,wall);box(scene,.22,7,14,11,3.45,0,wall);
box(scene,22,.2,14,0,7,0,dark);box(scene,22,.18,.12,0,.32,-6.85,woodL);
scene.add(new T.HemisphereLight("#fff5e6","#766958",2.8));
for(const x of [-8,-4,0,4,8]){const light=new T.SpotLight("#ffe8bb",65,18,Math.PI/3,.6,1);light.position.set(x,6.6,1);light.target.position.set(x,1.4,-1.5);scene.add(light,light.target)}
const sites=[[-7.8,-1.6],[-5.5,1.55],[-3.25,-1.6],[-.95,1.55],[1.35,-1.6],[3.65,1.55],[5.98,-1.6],[8.22,1.55]];
const displays=[];
for(let i=0;i<8;i++){
 const [x,z]=sites[i],g=new T.Group();g.position.set(x,0,z);g.userData.exhibit=i;scene.add(g);displays.push(g);
 box(g,1.95,.8,1.5,0,.4,0,paper);
 box(g,2.05,.08,1.58,0,.84,0,woodL);
 box(g,2.03,.08,1.58,0,2.92,0,woodL);
 for(const sx of [-.97,.97])for(const sz of [-.73,.73])box(g,.045,2,.045,sx,1.89,sz,gold);
 box(g,1.95,2,.025,0,1.88,-.74,glass);
 box(g,1.95,2,.025,0,1.88,.74,glass);
 for(const sx of [-.975,.975])box(g,.025,2,1.46,sx,1.88,0,glass);
}
// 0 Border gateway: paired columns and sign board
{const g=displays[0];for(const x of [-.4,.4]){cyl(g,.11,.13,1.18,x,1.5,-.08,wood);box(g,.3,.09,.29,x,2.12,-.08,gold)}
box(g,1.15,.15,.43,0,2.21,-.07,woodL);box(g,.9,.23,.045,0,2.04,.18,red);box(g,.48,.06,.05,0,2.06,.21,gold)}
// 1 Maimaichen trade houses with eaves and lanterns
{const g=displays[1];for(const x of [-.38,.38]){box(g,.58,.62,.58,x,1.24,0,wood);box(g,.73,.09,.73,x,1.56,0,red);const roof=cone(g,.54,.38,x,1.78,0,gold);roof.rotation.y=Math.PI/4;box(g,.16,.20,.04,x,1.31,.31,paper)}
for(const x of [-.8,.8]){cyl(g,.025,.025,.43,x,1.56,.2,gold);sphere(g,.10,x,1.32,.2,red)}}
// 2 Tea bricks: stacked blocks with raised brand stamps and seams
{const g=displays[2];box(g,1.6,.065,.9,0,1.01,0,wood);
for(let row=0;row<3;row++)for(let side=0;side<2;side++){
const x=(side-.5)*.68,y=1.13+row*.19,z=(row%2?-.08:.08);
box(g,.61,.17,.40,x,y,z,tea);box(g,.40,.018,.018,x,y+.035,z+.21,gold);
for(const dx of [-.12,.12])box(g,.025,.11,.015,x+dx,y,z+.218,paper);
}}
// 3 Tea chests, packages, crossed straps
{const g=displays[3];for(const [x,h,d] of [[-.39,.65,.53],[.32,.9,.62]]){const y=.91+h/2;
box(g,.72,h,d,x,y,-.03,wood);for(const sx of [-.28,.28])box(g,.05,h,.05,x+sx,y,d/2-.03,gold);
box(g,.28,.17,.03,x,y+.07,d/2,paper);box(g,.72,.035,.035,x,y+h/2-.06,d/2,gold)}
box(g,.95,.14,.5,0,1.97,0,cloth);}
// 4 Caravan: two recognizable camel-like animals and cargo bundles
{const g=displays[4];for(const [x,z] of [[-.38,-.08],[.3,.17]]){sphere(g,.22,x,1.32,z,cloth);
sphere(g,.15,x-.1,1.53,z,cloth);sphere(g,.14,x+.1,1.53,z,cloth);
const neck=cyl(g,.055,.06,.43,x+.22,1.52,z,cloth);neck.rotation.z=-.31;
sphere(g,.11,x+.27,1.73,z,cloth);sphere(g,.13,x+.37,1.76,z,cloth);
for(const dx of [-.13,.13])for(const dz of [-.11,.11])cyl(g,.045,.045,.49,x+dx,.99,z+dz,cloth);
box(g,.23,.19,.22,x,1.68,z-.17,wood);box(g,.23,.19,.22,x,1.68,z+.17,wood);
}}
// 5 Trade route: table-map, direction post, parcels
{const g=displays[5];box(g,1.2,.06,.75,0,1.15,0,wood);box(g,1.08,.025,.66,0,1.19,0,paper);
const trail=box(g,.74,.014,.034,0,1.22,0,red);trail.rotation.y=.4;
cyl(g,.045,.045,.84,-.52,1.61,.07,wood);box(g,.70,.29,.04,-.19,1.85,.07,paper);
box(g,.31,.24,.31,.50,1.3,-.11,woodL);}
// 6 Merchant's shop: canopy, shelves, goods, signage
{const g=displays[6];box(g,1.14,.07,.64,0,1.14,0,wood);
for(const x of [-.50,.50])cyl(g,.045,.045,.8,x,1.55,.25,wood);
box(g,1.27,.095,.82,0,1.95,0,red);box(g,1.02,.58,.47,0,1.42,-.12,wood);
for(const x of [-.28,0,.28])box(g,.20,.21,.21,x,1.40,.16,x===0?cloth:paper);
box(g,.48,.20,.03,0,1.77,.26,paper);}
// 7 Russian tea setting: samovar, tap, cups on tray
{const g=displays[7];const body=cyl(g,.17,.21,.53,0,1.48,-.14,gold);
cyl(g,.23,.23,.055,0,1.16,-.14,wood);
cyl(g,.15,.15,.07,0,1.79,-.14,gold);
cyl(g,.045,.045,.30,0,1.96,-.14,gold);
cone(g,.09,.13,0,2.12,-.14,gold);
for(const x of [-.27,.27]){const h=ring(g,.085,.021,x,1.46,-.14,gold);h.rotation.y=Math.PI/2}
const spout=cyl(g,.025,.025,.29,.02,1.33,.1,gold);spout.rotation.x=Math.PI/2;
box(g,.88,.045,.42,0,1.08,.29,woodL);
for(const x of [-.19,.19]){cyl(g,.08,.06,.09,x,1.18,.29,paper);const h=ring(g,.045,.01,x+.08,1.19,.29,paper);h.rotation.y=Math.PI/2}
}
// Camera controls and picking
let yaw=0,targetYaw=0,pitch=0,targetPitch=0,zoom=12.5,targetZoom=12.5,focus=0,targetFocus=0,drag=false,moved=false,px=0,py=0;
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
function resize(){const w=host.clientWidth,h=host.clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false)}
new ResizeObserver(resize).observe(host);resize();
const ray=new T.Raycaster(),mouse=new T.Vector2(),canvas=renderer.domElement;
canvas.addEventListener("pointerdown",e=>{drag=true;moved=false;px=e.clientX;py=e.clientY;canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener("pointermove",e=>{if(!drag)return;const dx=e.clientX-px,dy=e.clientY-py;moved ||= Math.abs(dx)+Math.abs(dy)>2;targetYaw=clamp(targetYaw-dx*.005,-1.3,1.3);targetPitch=clamp(targetPitch+dy*.003,-.3,.32);px=e.clientX;py=e.clientY});
canvas.addEventListener("pointerup",e=>{drag=false;if(moved)return;const r=canvas.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hits=ray.intersectObjects(displays,true);
if(hits.length){let obj=hits[0].object;while(obj&&obj.userData.exhibit===undefined)obj=obj.parent;if(obj){const i=obj.userData.exhibit;window.showExhibit?.(i);targetFocus=sites[i][0]*.53;targetZoom=8.4}}});
canvas.addEventListener("wheel",e=>{e.preventDefault();targetZoom=clamp(targetZoom+e.deltaY*.012,6,16)},{passive:false});
document.getElementById("left").onclick=()=>targetYaw=clamp(targetYaw-.28,-1.3,1.3);
document.getElementById("right").onclick=()=>targetYaw=clamp(targetYaw+.28,-1.3,1.3);
document.getElementById("zoomIn").onclick=()=>targetZoom=clamp(targetZoom-.9,6,16);
document.getElementById("zoomOut").onclick=()=>targetZoom=clamp(targetZoom+.9,6,16);
document.getElementById("reset").onclick=()=>{targetYaw=targetPitch=targetFocus=0;targetZoom=12.5};
const clock=new T.Clock();function frame(){requestAnimationFrame(frame);const k=1-Math.exp(-5*Math.min(.05,clock.getDelta()));yaw+=(targetYaw-yaw)*k;pitch+=(targetPitch-pitch)*k;zoom+=(targetZoom-zoom)*k;focus+=(targetFocus-focus)*k;camera.position.set(focus+Math.sin(yaw)*zoom,3.1+pitch*5,2.8+Math.cos(yaw)*zoom);camera.lookAt(focus,1.65,-1);renderer.render(scene,camera)}frame();
}catch(err){console.error(err);note.style.display="block";note.textContent="3D rendering unavailable; see the exhibit descriptions."}
}